#define main preserved_production_main
#include "train_yaoyao_graph_gpuval.cu"
#undef main
#include <random>
int main(int argc,char**argv){try{using namespace tao::dual;if(argc!=3)throw std::runtime_error("fixed|shuffle unique_output_prefix");std::string arm=argv[1],prefix=argv[2];if(arm!="fixed"&&arm!="shuffle")throw std::runtime_error("arm");if(!std::filesystem::exists("build/STOP_TRAINING"))throw std::runtime_error("production must stay stopped");if(std::filesystem::exists(prefix+".dsb")||std::filesystem::exists(prefix+".manifest"))throw std::runtime_error("output exists");std::string th;tao::text::load_tokenizer("build/formal_tokenizer.bbp",th);std::ifstream f("build/bpe_pilot_train.bin",std::ios::binary);std::string raw((std::istreambuf_iterator<char>(f)),{});auto dh=tao::text::sha256(raw);std::istringstream in(raw);SortedGpuTrainer tr(initialize(Config{},713));SequenceSlots slots(tr,4);tao::data::PilotCursor cursor(tao::data::read_bpe_pilot(in,th),4,false);auto id=checkpoint_identity(tr.graph.c,dh,th,200)+"arch2-controlled-v1-external-lr\n";restore(load_slot_file("build/yaoyao_graph_step_1200.scp",id,capture(slots,cursor),cursor),slots,cursor);cursor.next=0;for(auto&c:cursor.slots)c=tao::data::Cursor{};for(auto*ss:{&slots.s,&slots.m})for(auto&slot:*ss)for(auto&v:slot)check(cudaMemset(v->value.p,0,v->value.n*4));if(arm=="shuffle"){std::mt19937_64 rng(20260909);std::shuffle(cursor.docs.begin(),cursor.docs.end(),rng);}std::ofstream manifest(prefix+".manifest");manifest<<"pilot nonresumable effective export only\nsource=step1200 lr=.00025 updates=40 seed=20260909 arm="<<arm<<"\nmatched_fresh_epoch_state_reset=1 dataset="<<dh<<"\n";for(size_t i=0;i<cursor.docs.size();++i){std::string b;for(auto&t:cursor.docs[i]){b+=char(t.id);b+=char(t.id>>8);b+=char(t.loss);}manifest<<i<<" "<<tao::text::sha256(b)<<"\n";}manifest.close();fixed_validation::Evaluator eval(tr,fixed_validation::Corpus("build/bpe_pilot_validation.bin","build/formal_tokenizer.bbp",fixed_validation::Corpus::fixed_dataset_sha256,th));auto v=eval.run();printf("INITIAL arm=%s step=%u NLL=%.12f\n",arm.c_str(),tr.steps,v.nll());fflush(stdout);ReusableBatchGraph replay(tr,4,256);DeferredLoss loss(1024);size_t totaln=0,totalp=0;for(int k=0;k<40;++k){if(std::filesystem::exists("build/STOP_REPAIR"))break;size_t n=0,p=0;for(int j=0;j<8;++j){auto plan=tao::data::take_batch(cursor,256);if(!plan.timesteps)continue;replay.run(plan,slots);accumulate_loss<<<1,1>>>(replay.data.loss.p,replay.data.loss.n,loss.total,loss.bad);n+=plan.supervised;p+=plan.positions;}if(!n)throw std::runtime_error("empty supervision");double l=loss.collect();float norm=tr.update(n,.00025f);auto result=eval.run();totaln+=n;totalp+=p;printf("PILOT arm=%s step=%u supervised=%zu positions=%zu train_NLL=%.9f validation_NLL=%.12f norm=%.6f total_supervised=%zu total_positions=%zu\n",arm.c_str(),tr.steps,n,p,l/n,result.nll(),norm,totaln,totalp);fflush(stdout);}CpuModel cpu(tr.graph.c);for(auto&kv:cpu.w)kv.second=tr.graph.w.at(kv.first)->value.host();save_bundle(cpu,prefix+".dsb",th);printf("DONE step=%u artifact=%s.dsb nonresumable=1\n",tr.steps,prefix.c_str());return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
